using System;
using System.IO;
using System.Linq;
using Unity.FPS.Game;
using Unity.FPS.Gameplay;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEditor.TestTools.TestRunner.Api;
using UnityEngine;
using UnityEngine.SceneManagement;
using Object=UnityEngine.Object;
namespace IronRequiem.Editor
{
    [InitializeOnLoad]public static class PrimaryCapsulesAuthoring
    {
        public const string Weapon="Assets/IronRequiem/Prefabs/Weapons/Weapon_IR_PrimaryCapsules_v03.prefab",Projectile="Assets/IronRequiem/Prefabs/Weapons/Projectile_IR_PrimaryCapsules_v03.prefab",Player="Assets/IronRequiem/Prefabs/Player/Player_PrimaryCapsules_v03.prefab",Lab="Assets/IronRequiem/Scenes/PrimaryCapsulesLab.unity",Reports="Tools/IronRequiem/Reports/PrimaryCapsules";
        const string Queue="Tools/IronRequiem/Requests/primary-capsules.txt",Key="IRON.PrimaryCapsules";static readonly DateTime LoadedAt=DateTime.UtcNow;static TestRunnerApi api;
        static PrimaryCapsulesAuthoring(){EditorApplication.update+=Tick;if(SessionState.GetBool(Key+".testing",false))EditorApplication.delayCall+=Register;}
        static bool Dirty()=>Enumerable.Range(0,SceneManager.sceneCount).Any(i=>SceneManager.GetSceneAt(i).isDirty);
        static void Register(){if(!api){api=ScriptableObject.CreateInstance<TestRunnerApi>();api.RegisterCallbacks(new Results());}}
        static void Tick(){if(EditorApplication.isCompiling||EditorApplication.isUpdating||EditorApplication.isPlayingOrWillChangePlaymode||SessionState.GetBool(Key+".testing",false))return;if(SessionState.GetBool(Key+".restore",false)&&EditorApplication.timeSinceStartup-SessionState.GetFloat(Key+".at",0)>3){SessionState.EraseBool(Key+".restore");if(!Dirty())EditorSceneManager.OpenScene(Lab);}if(!File.Exists(Queue)||LoadedAt<File.GetLastWriteTimeUtc("Assets/IronRequiem/Editor/PrimaryCapsulesAuthoring.cs")||LoadedAt<File.GetLastWriteTimeUtc("Assets/IronRequiem/Tests/PlayMode/PrimaryModuleTests.cs"))return;var op=File.ReadAllText(Queue).Trim();File.Delete(Queue);Directory.CreateDirectory(Reports);try{if(op=="build"){Build();File.WriteAllText(Queue,"test");}else if(op=="test")Run(new[]{"IronRequiem.Tests.PrimaryModuleTests.CapsulesMountAndAutomatic","IronRequiem.Tests.PrimaryModuleTests.CapsulesCommonTimeToKill","IronRequiem.Tests.PrimaryModuleTests.CapsulesBigBotTimeToKill"});else if(op=="verify")Verify();else throw new InvalidOperationException("Unknown capsule operation");}catch(Exception e){File.WriteAllText(Reports+"/error.txt",e.ToString());Debug.LogException(e);}}
        static void Variant(string source,string dest){if(File.Exists(dest))throw new InvalidOperationException("Preserve existing "+dest);var scene=EditorSceneManager.NewPreviewScene();try{var go=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(source),scene);go.name=Path.GetFileNameWithoutExtension(dest);PrefabUtility.SaveAsPrefabAsset(go,dest);}finally{EditorSceneManager.ClosePreviewScene(scene);}}
        static void Build(){if(Dirty())throw new InvalidOperationException("Preserving dirty user scene");Variant(PrimaryModuleAuthoring.Weapon,Weapon);Variant(PrimaryModuleAuthoring.Projectile,Projectile);Variant(PrimaryModuleAuthoring.Player,Player);var go=PrefabUtility.LoadPrefabContents(Projectile);try{go.GetComponent<ProjectileStandard>().Damage=5.5f;PrefabUtility.SaveAsPrefabAsset(go,Projectile);}finally{PrefabUtility.UnloadPrefabContents(go);}
            var template=PrefabUtility.LoadPrefabContents("Assets/FPS/Prefabs/Weapons/Weapon_Blaster.prefab");go=PrefabUtility.LoadPrefabContents(Weapon);try{var weapon=go.GetComponent<WeaponController>();var reference=template.GetComponent<WeaponController>();weapon.DelayBetweenShots=reference.DelayBetweenShots;weapon.ShootType=reference.ShootType;weapon.ProjectilePrefab=AssetDatabase.LoadAssetAtPath<GameObject>(Projectile).GetComponent<ProjectileBase>();weapon.MaxAmmo=64;weapon.AmmoReloadRate=64;weapon.AmmoReloadDelay=.28f;var socket=go.GetComponentsInChildren<Transform>(true).Single(t=>t.name=="Attachment");var assembly=new GameObject("TemplateCapsules").transform;assembly.SetParent(weapon.WeaponRoot.transform,false);
                for(int i=0;i<4;i++){var source=template.GetComponentsInChildren<Transform>(true).Single(t=>t.name=="Primary_Weapon_Container_0"+(i+1));var cell=Object.Instantiate(source.gameObject,assembly);cell.name="Capsule_"+(i+1);foreach(var ps in cell.GetComponentsInChildren<ParticleSystem>(true))Object.DestroyImmediate(ps.gameObject);foreach(var collider in cell.GetComponentsInChildren<Collider>(true))Object.DestroyImmediate(collider);foreach(var script in cell.GetComponentsInChildren<MonoBehaviour>(true))Object.DestroyImmediate(script);int side=i<2?1:-1;cell.transform.localScale=Vector3.one*.216f;cell.transform.rotation=weapon.WeaponMuzzle.rotation*Quaternion.Euler(0,180,side*23.62f);cell.transform.position=socket.position+weapon.WeaponMuzzle.rotation*new Vector3(side*.039f,.046f,i%2==0?.105f:.225f);foreach(var r in cell.GetComponentsInChildren<Renderer>())r.enabled=true;}
                PrefabUtility.SaveAsPrefabAsset(go,Weapon);
            }finally{PrefabUtility.UnloadPrefabContents(go);PrefabUtility.UnloadPrefabContents(template);}
            go=PrefabUtility.LoadPrefabContents(Player);try{var manager=go.GetComponent<PlayerWeaponsManager>();var weapon=AssetDatabase.LoadAssetAtPath<GameObject>(Weapon).GetComponent<WeaponController>();for(int i=0;i<manager.StartingWeapons.Count;i++)if(manager.StartingWeapons[i].name=="Weapon_IR_PrimaryModule_v02")manager.StartingWeapons[i]=weapon;var hands=new SerializedObject(go.GetComponent<ProtagonistHandsPresentation>());hands.FindProperty("pistolPrefab").objectReferenceValue=weapon;hands.ApplyModifiedPropertiesWithoutUndo();PrefabUtility.SaveAsPrefabAsset(go,Player);}finally{PrefabUtility.UnloadPrefabContents(go);}
            if(File.Exists(Lab))throw new InvalidOperationException("Preserve existing capsule lab");AssetDatabase.CopyAsset(PrimaryModuleAuthoring.Lab,Lab);var scene=EditorSceneManager.OpenScene(Lab);var old=Object.FindAnyObjectByType<PlayerCharacterController>().gameObject;var player=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(Player),scene);player.transform.SetPositionAndRotation(old.transform.position,old.transform.rotation);Object.DestroyImmediate(old);var surface=Object.FindAnyObjectByType<Unity.AI.Navigation.NavMeshSurface>();surface.RemoveData();surface.navMeshData=AssetDatabase.LoadAssetAtPath<UnityEngine.AI.NavMeshData>(PrimaryModuleAuthoring.Art+"/PrimaryModule_NavMesh.asset");surface.AddData();EditorUtility.SetDirty(surface);EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();}
        static void Run(string[] tests){if(Dirty())throw new InvalidOperationException("Preserving dirty user scene");Register();SessionState.SetBool(Key+".testing",true);api.Execute(new ExecutionSettings(new Filter{testMode=TestMode.PlayMode,testNames=tests}));}
        static void Verify(){int missing=0;foreach(var path in new[]{Player,Weapon,Projectile}){var go=PrefabUtility.LoadPrefabContents(path);try{foreach(var t in go.GetComponentsInChildren<Transform>(true))missing+=GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(t.gameObject);}finally{PrefabUtility.UnloadPrefabContents(go);}}if(missing>0)throw new InvalidOperationException("Missing scripts="+missing);IronRequiemSetupTools.WriteAudit();File.WriteAllText(Reports+"/references.txt","3 capsule variants: no missing scripts; existing controller/projectile code and stolen weapons preserved");}
        sealed class Results:IErrorCallbacks{public void RunStarted(ITestAdaptor t){}public void TestStarted(ITestAdaptor t){}public void TestFinished(ITestResultAdaptor t){}public void OnError(string message){SessionState.EraseBool(Key+".testing");File.WriteAllText(Reports+"/runner-error.txt",message);}public void RunFinished(ITestResultAdaptor result){if(!SessionState.GetBool(Key+".testing",false))return;SessionState.EraseBool(Key+".testing");TestRunnerApi.SaveResultToFile(result,Reports+"/play.xml");File.WriteAllText(Reports+"/status.txt",result.ResultState+" passed="+result.PassCount+" failed="+result.FailCount);SessionState.SetBool(Key+".restore",true);SessionState.SetFloat(Key+".at",(float)EditorApplication.timeSinceStartup);}}
    }
}